import 'dart:io';
import 'package:flutter/material.dart';
import 'package:image_picker/image_picker.dart';
import '../../core/network/api.dart';
import '../complaints/complaint_screens.dart';
class TasksScreen extends StatefulWidget{const TasksScreen({super.key,required this.api,required this.history});final ClyraApi api;final bool history;@override State<TasksScreen> createState()=>_TasksScreenState();}
class _TasksScreenState extends State<TasksScreen>{late Future<dynamic> future;@override void initState(){super.initState();refresh();}void refresh(){setState(()=>future=widget.api.get('/assignments?limit=100'));}
Future<void> act(Map task,String action)async{final reason=TextEditingController();final files=<File>[];if(action=='hold'||action=='submit-resolution'){
 final result=await showDialog<bool>(context:context,builder:(context)=>StatefulBuilder(builder:(context,update)=>AlertDialog(title:Text(action=='hold'?'Hold work':'Submit completion'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:reason,decoration:InputDecoration(labelText:action=='hold'?'Hold reason':'Work remarks')),if(action=='submit-resolution')TextButton(onPressed:()async{final images=await ImagePicker().pickMultiImage();update(()=>files.addAll(images.map((x)=>File(x.path))));},child:Text('Add evidence images (${files.length})'))]),actions:[TextButton(onPressed:()=>Navigator.pop(context,false),child:const Text('Cancel')),TextButton(onPressed:()=>Navigator.pop(context,true),child:const Text('Confirm'))])));
 if(result!=true)return;
 if(action=='submit-resolution'&&files.isEmpty){if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Evidence required')));return;}
 }
 try{final id=task['_id'];if(action=='submit-resolution'){final urls=<String>[];for(final f in files){final item=await widget.api.uploadImage(f,complaintId:task['complaintId'].toString(),resourceType:'EVIDENCE');urls.add(item['url'].toString());}await widget.api.post('/assignments/$id/submit-resolution',{'evidenceUrls':urls,'remarks':reason.text.length>=4?reason.text:'Work completed'});}else{await widget.api.post('/assignments/$id/$action',action=='hold'?{'reason':reason.text}:{});}refresh();if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Task updated')));}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString())));}finally{reason.dispose();}
}
@override Widget build(BuildContext context)=>FutureBuilder<dynamic>(future:future,builder:(context,s){if(s.connectionState!=ConnectionState.done)return const Center(child:CircularProgressIndicator());if(s.hasError)return Center(child:Text('Task error: ${s.error}'));final all=(s.data as List?)??[];final tasks=all.where((t)=>widget.history?['COMPLETED','REASSIGNED'].contains(t['assignmentStatus']):!['COMPLETED','REASSIGNED'].contains(t['assignmentStatus'])).toList();if(tasks.isEmpty)return const Center(child:Text('No assigned tasks in this section.'));return RefreshIndicator(onRefresh:()async{refresh();await future;},child:ListView(padding:const EdgeInsets.all(16),children:[for(final task in tasks)Card(margin:const EdgeInsets.only(bottom:12),child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Task ${task['_id'].toString().substring(12)}',style:const TextStyle(fontWeight:FontWeight.bold,fontSize:16)),const SizedBox(height:6),Chip(label:Text(task['assignmentStatus'].toString().replaceAll('_',' '))),const SizedBox(height:8),TextButton.icon(onPressed:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>ComplaintDetail(api:widget.api,complaintId:task['complaintId'].toString()))),icon:const Icon(Icons.open_in_new),label:const Text('View complaint & timeline')),if(!widget.history)...[if(task['assignmentStatus']=='PENDING')ElevatedButton(onPressed:()=>act(task,'accept'),child:const Text('Accept task')),if(task['assignmentStatus']=='ACCEPTED')ElevatedButton(onPressed:()=>act(task,'start'),child:const Text('Start work')),if(task['assignmentStatus']=='IN_PROGRESS')...[OutlinedButton(onPressed:()=>act(task,'hold'),child:const Text('Put on hold')),ElevatedButton(onPressed:()=>act(task,'submit-resolution'),child:const Text('Submit completion evidence'))],if(task['assignmentStatus']=='ON_HOLD')ElevatedButton(onPressed:()=>act(task,'resume'),child:const Text('Resume work'))]]))) ]));});}
}
